from src.dijkstra import dijkstra

def test_simple_path():
    g = {'A': [('B', 1), ('C', 4)], 'B': [('C', 2), ('D', 5)], 'C': [('D', 1)], 'D': []}
    d = dijkstra(g, 'A')
    assert d['A'] == 0
    assert d['B'] == 1
    assert d['C'] == 3
    assert d['D'] == 4

def test_source_only():
    g = {'A': []}
    d = dijkstra(g, 'A')
    assert d == {'A': 0}

def test_disconnected():
    g = {'A': [('B', 1)], 'C': []}
    d = dijkstra(g, 'A')
    assert d['A'] == 0
    assert d['B'] == 1
    assert 'C' not in d

def test_multiple_paths():
    g = {'S': [('A', 10), ('B', 3)], 'A': [('E', 2)], 'B': [('A', 4), ('E', 15)], 'E': []}
    d = dijkstra(g, 'S')
    assert d['S'] == 0
    assert d['B'] == 3
    assert d['A'] == 7
    assert d['E'] == 9
